-- # Each parameter of each routine in ROUTINES, ordered by its ordinal position
-- # (6.31, Description, 1 and 2). Every parameter is an IN parameter
-- # (Description, 4), and a built-in function's parameters have names
-- # (Description, 7.a). Its data type is described like the data type of a
-- # column, and is identified by its ordinal position.
SELECT * FROM information_schema.parameters WHERE specific_name = 'GCD_1';
-- SPECIFIC_CATALOG: :memory: SPECIFIC_SCHEMA: VSQL SPECIFIC_NAME: GCD_1 ORDINAL_POSITION: 1 PARAMETER_MODE: IN IS_RESULT: NO AS_LOCATOR: NO PARAMETER_NAME: A FROM_SQL_SPECIFIC_CATALOG: NULL FROM_SQL_SPECIFIC_SCHEMA: NULL FROM_SQL_SPECIFIC_NAME: NULL TO_SQL_SPECIFIC_CATALOG: NULL TO_SQL_SPECIFIC_SCHEMA: NULL TO_SQL_SPECIFIC_NAME: NULL DATA_TYPE: SMALLINT CHARACTER_MAXIMUM_LENGTH: NULL CHARACTER_OCTET_LENGTH: NULL CHARACTER_SET_CATALOG: NULL CHARACTER_SET_SCHEMA: NULL CHARACTER_SET_NAME: NULL COLLATION_CATALOG: NULL COLLATION_SCHEMA: NULL COLLATION_NAME: NULL NUMERIC_PRECISION: 16 NUMERIC_PRECISION_RADIX: 2 NUMERIC_SCALE: 0 DATETIME_PRECISION: NULL INTERVAL_TYPE: NULL INTERVAL_PRECISION: NULL UDT_CATALOG: NULL UDT_SCHEMA: NULL UDT_NAME: NULL SCOPE_CATALOG: NULL SCOPE_SCHEMA: NULL SCOPE_NAME: NULL MAXIMUM_CARDINALITY: NULL DTD_IDENTIFIER: 1
-- SPECIFIC_CATALOG: :memory: SPECIFIC_SCHEMA: VSQL SPECIFIC_NAME: GCD_1 ORDINAL_POSITION: 2 PARAMETER_MODE: IN IS_RESULT: NO AS_LOCATOR: NO PARAMETER_NAME: B FROM_SQL_SPECIFIC_CATALOG: NULL FROM_SQL_SPECIFIC_SCHEMA: NULL FROM_SQL_SPECIFIC_NAME: NULL TO_SQL_SPECIFIC_CATALOG: NULL TO_SQL_SPECIFIC_SCHEMA: NULL TO_SQL_SPECIFIC_NAME: NULL DATA_TYPE: SMALLINT CHARACTER_MAXIMUM_LENGTH: NULL CHARACTER_OCTET_LENGTH: NULL CHARACTER_SET_CATALOG: NULL CHARACTER_SET_SCHEMA: NULL CHARACTER_SET_NAME: NULL COLLATION_CATALOG: NULL COLLATION_SCHEMA: NULL COLLATION_NAME: NULL NUMERIC_PRECISION: 16 NUMERIC_PRECISION_RADIX: 2 NUMERIC_SCALE: 0 DATETIME_PRECISION: NULL INTERVAL_TYPE: NULL INTERVAL_PRECISION: NULL UDT_CATALOG: NULL UDT_SCHEMA: NULL UDT_NAME: NULL SCOPE_CATALOG: NULL SCOPE_SCHEMA: NULL SCOPE_NAME: NULL MAXIMUM_CARDINALITY: NULL DTD_IDENTIFIER: 2

-- # A character string parameter can have any length.
SELECT ordinal_position, data_type, character_maximum_length, numeric_precision FROM information_schema.parameters WHERE specific_name = 'SPLIT_PART_1';
-- ORDINAL_POSITION: 1 DATA_TYPE: CHARACTER VARYING CHARACTER_MAXIMUM_LENGTH: 10485760 NUMERIC_PRECISION: NULL
-- ORDINAL_POSITION: 2 DATA_TYPE: CHARACTER VARYING CHARACTER_MAXIMUM_LENGTH: 10485760 NUMERIC_PRECISION: NULL
-- ORDINAL_POSITION: 3 DATA_TYPE: BIGINT CHARACTER_MAXIMUM_LENGTH: NULL NUMERIC_PRECISION: 64

-- # An overload with fewer parameters has the first names. No name is a
-- # reserved word, so it never needs to be quoted.
SELECT specific_name, ordinal_position, parameter_name FROM information_schema.parameters WHERE specific_name IN ('ROUND_1', 'ROUND_2', 'MAKE_TIME_1');
-- SPECIFIC_NAME: MAKE_TIME_1 ORDINAL_POSITION: 1 PARAMETER_NAME: HOURS
-- SPECIFIC_NAME: MAKE_TIME_1 ORDINAL_POSITION: 2 PARAMETER_NAME: MINUTES
-- SPECIFIC_NAME: MAKE_TIME_1 ORDINAL_POSITION: 3 PARAMETER_NAME: SECONDS
-- SPECIFIC_NAME: ROUND_1 ORDINAL_POSITION: 1 PARAMETER_NAME: X
-- SPECIFIC_NAME: ROUND_2 ORDINAL_POSITION: 1 PARAMETER_NAME: X
-- SPECIFIC_NAME: ROUND_2 ORDINAL_POSITION: 2 PARAMETER_NAME: PLACES

-- # Every parameter of a built-in function has a name.
SELECT COUNT(*) FROM information_schema.parameters WHERE parameter_name IS NULL;
-- COL1: 0

-- # A variadic function, such as CONCAT, has a last parameter named VARIADIC
-- # for the rest of its arguments. It's an ARRAY, without a maximum
-- # cardinality or any other type information.
SELECT specific_name, ordinal_position, parameter_name, data_type, character_maximum_length, character_set_name, numeric_precision, maximum_cardinality, dtd_identifier FROM information_schema.parameters WHERE specific_name IN ('CONCAT_1', 'CONCAT_WS_1');
-- SPECIFIC_NAME: CONCAT_1 ORDINAL_POSITION: 1 PARAMETER_NAME: VARIADIC DATA_TYPE: ARRAY CHARACTER_MAXIMUM_LENGTH: NULL CHARACTER_SET_NAME: NULL NUMERIC_PRECISION: NULL MAXIMUM_CARDINALITY: NULL DTD_IDENTIFIER: 1
-- SPECIFIC_NAME: CONCAT_WS_1 ORDINAL_POSITION: 1 PARAMETER_NAME: SEPARATOR DATA_TYPE: CHARACTER VARYING CHARACTER_MAXIMUM_LENGTH: 10485760 CHARACTER_SET_NAME: UTF8 NUMERIC_PRECISION: NULL MAXIMUM_CARDINALITY: NULL DTD_IDENTIFIER: 1
-- SPECIFIC_NAME: CONCAT_WS_1 ORDINAL_POSITION: 2 PARAMETER_NAME: VARIADIC DATA_TYPE: ARRAY CHARACTER_MAXIMUM_LENGTH: NULL CHARACTER_SET_NAME: NULL NUMERIC_PRECISION: NULL MAXIMUM_CARDINALITY: NULL DTD_IDENTIFIER: 2

-- # The parameters of the PostgreSQL functions have names too.
/* postgresql */
SELECT p.specific_name, p.parameter_name FROM information_schema.parameters AS p JOIN information_schema.routines AS r ON r.specific_name = p.specific_name WHERE r.routine_name = 'OBJ_DESCRIPTION';
-- SPECIFIC_NAME: OBJ_DESCRIPTION_1 PARAMETER_NAME: OBJECT
-- SPECIFIC_NAME: OBJ_DESCRIPTION_1 PARAMETER_NAME: CATALOG_NAME

-- # A routine without parameters, such as PI, has no rows. Every parameter
-- # belongs to a routine in ROUTINES.
SELECT COUNT(*) FROM information_schema.parameters WHERE specific_name = 'PI_1';
SELECT COUNT(*) FROM information_schema.parameters AS p WHERE NOT EXISTS (SELECT * FROM information_schema.routines AS r WHERE r.specific_name = p.specific_name);
-- COL1: 0
-- COL1: 0

-- # The short name view PARAMETERS_S has the same rows (5.77).
SELECT specific_name, ordinal_position, from_sql_spec_cat, to_sql_spec_name, char_max_length, numeric_prec_radix, max_cardinality FROM information_schema.parameters_s WHERE specific_name = 'SPLIT_PART_1';
-- SPECIFIC_NAME: SPLIT_PART_1 ORDINAL_POSITION: 1 FROM_SQL_SPEC_CAT: NULL TO_SQL_SPEC_NAME: NULL CHAR_MAX_LENGTH: 10485760 NUMERIC_PREC_RADIX: NULL MAX_CARDINALITY: NULL
-- SPECIFIC_NAME: SPLIT_PART_1 ORDINAL_POSITION: 2 FROM_SQL_SPEC_CAT: NULL TO_SQL_SPEC_NAME: NULL CHAR_MAX_LENGTH: 10485760 NUMERIC_PREC_RADIX: NULL MAX_CARDINALITY: NULL
-- SPECIFIC_NAME: SPLIT_PART_1 ORDINAL_POSITION: 3 FROM_SQL_SPEC_CAT: NULL TO_SQL_SPEC_NAME: NULL CHAR_MAX_LENGTH: NULL NUMERIC_PREC_RADIX: 2 MAX_CARDINALITY: NULL
